def bootstrap(f, stack=[]):

	def wrappedfunc(*args, **kwargs):
		if stack:
			return f(*args, **kwargs)
		else:
			to = f(*args, **kwargs)
			while True:
				if type(to) is GeneratorType:
					stack.append(to)
					to = next(to)
				else:
					stack.pop()
					if not stack:
						break
					to = stack[-1].send(to)
			return to
	return wrappedfunc
MA = 10 ** 5 + 1
level = 20
tree = [[] for i in range(MA)]
depth = [0 for i in range(MA)]
parent = [[0 for i in range(level)] for j in range(MA)]

@bootstrap
def dfs(cur, prev):
	depth[cur] = depth[prev] + 1
	parent[cur][0] = prev
	for i in range(len(tree[cur])):
		if tree[cur][i] != prev:
			yield dfs(tree[cur][i], cur)
	yield

def precomputeSparseMatrix(n):
	for i in range(1, level):
		for node in range(1, n + 1):
			if parent[node][i - 1] != -1:
				parent[node][i] = parent[parent[node][i - 1]][i - 1]

def lca(u, v):
	if depth[v] < depth[u]:
		(u, v) = (v, u)
	diff = depth[v] - depth[u]
	for i in range(level):
		if diff >> i & 1:
			v = parent[v][i]
	if u == v:
		return u
	i = level - 1
	while i >= 0:
		if parent[u][i] != parent[v][i]:
			u = parent[u][i]
			v = parent[v][i]
		i += -1
	return parent[u][0]

def add(a, b):
	tree[a].append(b)
	tree[b].append(a)

def res(s, t, f):
	p = lca(t, f)
	q = lca(s, f)
	if p == q:
		r = depth[lca(s, t)] - depth[p]
		return min(depth[p] + depth[f] - 2 * depth[p] + 1 + r, depth[q] + depth[f] - 2 * depth[q] + 1 + r)
	return min(depth[p] + depth[f] - 2 * depth[p] + 1, depth[q] + depth[f] - 2 * depth[q] + 1)
